using System.Net;
using System.Text.Json;
using Htt.Host.Api;
using Htt.Host.Api.MasterData;
using Htt.Infrastructure.Documents;
using Npgsql;
using Xunit;
using static Htt.IntegrationTests.SalesFlowSupport;
namespace Htt.IntegrationTests;
public sealed class CrmMapTests:IAsyncLifetime
{
 private readonly DatabaseFixture db=new();public Task InitializeAsync()=>db.InitializeAsync();public Task DisposeAsync()=>db.DisposeAsync();private Task<object?> S(string sql,params(string,object)[]args)=>db.OwnerScalarAsync(sql,args);private static Guid Id(JsonElement e)=>e.GetProperty("id").GetGuid();
 private async Task<(Guid Customer,Guid Branch)> Branch(HttpClient c,string suburb="Sydney",string state="NSW",string postcode="2000") {var customer=await Create(c,"/customers",new CustomerDraft(Code(),"Map client",null));return(customer,await Create(c,$"/customers/{customer}/branches",new BranchMaintenance(Code(),"Showroom","10 Test Street",suburb,state,postcode)));}
 private static Task<HttpResponseMessage> Queue(HttpClient c,Guid branch,string? key=null,long version=1)=>Send(c,HttpMethod.Post,$"/crm/branches/{branch}/geocode",version:version,key:key);
 private static Task<HttpResponseMessage> Coordinates(HttpClient c,Guid branch,decimal lat=-33.86m,decimal lng=151.21m,long version=1,string? key=null)=>Send(c,HttpMethod.Put,$"/crm/branches/{branch}/coordinates",new BranchCoordinates(lat,lng,"Staff verified site"),version,key);
 private sealed class Geocoder(string? error=null,Func<Task>? callback=null):IBranchGeocoder{public int Calls;public async Task<JsonElement> LocateAsync(JsonElement address,CancellationToken ct){Calls++;Assert.Equal("AU",address.GetProperty("country").GetString());if(callback is not null)await callback();if(error is not null)throw new DocumentWorkException(error,WorkFailure.Retry);return JsonSerializer.SerializeToElement(new{latitude=-33.86m,longitude=151.21m,precision="ROOFTOP",placeId="test-sydney"});}}
 private async Task Run(Geocoder fake){await S("DELETE FROM crm.geocode_jobs WHERE company_id<>@c",("c",db.Company));await using var source=NpgsqlDataSource.Create(db.Worker);Assert.True(await new GeocodeWorker(source,fake).ProcessOneAsync());}
 [Fact]public async Task Manual_coordinates_map_filters_and_encoded_navigation_have_no_financial_fields()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Branch(c);var b=await Branch(c,"Melbourne","VIC","3000");await Expect(await Coordinates(c,a.Branch),HttpStatusCode.OK);await Expect(await Coordinates(c,b.Branch,-37.81m,144.96m),HttpStatusCode.OK);var items=(await Get(c,"/crm/map/branches?state=NSW&status=ACTIVE&geocodeState=LOCATED&q=Showroom&south=-34&north=-33&west=151&east=152")).GetProperty("items");Assert.Single(items.EnumerateArray());Assert.Equal(a.Branch,Id(items[0]));Assert.Equal("MANUAL",items[0].GetProperty("source").GetString());Assert.False(items[0].TryGetProperty("creditLimit",out _));var nav=await Get(c,$"/crm/branches/{a.Branch}/navigation?provider=APPLE");Assert.StartsWith("https://maps.apple.com/",nav.GetProperty("url").GetString());Assert.True(nav.GetProperty("usesCoordinates").GetBoolean());}
 [Fact]public async Task Unlocated_branch_navigation_uses_authorized_address_and_bounds_exclude_it()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var nav=await Get(c,$"/crm/branches/{b.Branch}/navigation");Assert.False(nav.GetProperty("usesCoordinates").GetBoolean());Assert.Contains("10%20Test%20Street",nav.GetProperty("url").GetString());Assert.Empty((await Get(c,"/crm/map/branches?south=-90&north=90&west=-180&east=180")).GetProperty("items").EnumerateArray());}
 [Fact]public async Task Date_line_bounds_and_pagination_filter_on_authorized_rows()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Branch(c);var b=await Branch(c);await Expect(await Coordinates(c,a.Branch,0,179),HttpStatusCode.OK);await Expect(await Coordinates(c,b.Branch,0,-179),HttpStatusCode.OK);var map=await Get(c,"/crm/map/branches?south=-1&north=1&west=170&east=-170&pageSize=1");Assert.Equal(2,map.GetProperty("total").GetInt32());Assert.Single(map.GetProperty("items").EnumerateArray());}
 [Theory][InlineData("?south=0")][InlineData("?south=10&north=-10&west=-180&east=180")][InlineData("?state=BAD")][InlineData("?pageSize=101")]
 public async Task Invalid_map_filters_are_rejected(string query)
 {await using var api=new TestApi(db);using var c=api.Authenticated();await Expect(await Send(c,HttpMethod.Get,"/crm/map/branches"+query),HttpStatusCode.UnprocessableEntity);}
 [Fact]public async Task Map_customer_assignment_and_navigation_scope_are_enforced()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var a=await Branch(c);var b=await Branch(c);var sales=await Staff(db,"SALES");await S("INSERT INTO identity.customer_assignments(company_id,membership_id,customer_id)VALUES(@c,@m,@customer)",("c",db.Company),("m",sales.Membership),("customer",a.Customer));using var limited=api.Authenticated(sales.Subject);Assert.Single((await Get(limited,"/crm/map/branches")).GetProperty("items").EnumerateArray());await Expect(await Send(limited,HttpMethod.Get,$"/crm/branches/{b.Branch}/navigation"),HttpStatusCode.Forbidden);await Expect(await Queue(limited,a.Branch),HttpStatusCode.Forbidden);using var foreign=api.Authenticated(company:db.OtherCompany);await Expect(await Send(foreign,HttpMethod.Get,$"/crm/branches/{a.Branch}/navigation"),HttpStatusCode.NotFound);}
 [Theory][InlineData(true)][InlineData(false)]public async Task Concurrent_queue_reuses_one_job_per_address_version(bool sameKey)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var key=Code();var all=await Task.WhenAll(Queue(c,b.Branch,key),Queue(c,b.Branch,sameKey?key:Code()));var a=await Expect(all[0],HttpStatusCode.Accepted);var z=await Expect(all[1],HttpStatusCode.Accepted);Assert.Equal(Id(a),Id(z));Assert.Equal(1L,await S("SELECT count(*)FROM crm.geocode_jobs WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Geocode_result_has_precision_attribution_30_day_expiry_and_no_raw_coordinates_in_sync_events()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));await Run(new());Assert.Equal("SUCCEEDED",(await Get(c,$"/crm/geocode-jobs/{id}")).GetProperty("state").GetString());var item=(await Get(c,"/crm/map/branches?geocodeState=LOCATED")).GetProperty("items")[0];Assert.Equal("ROOFTOP",item.GetProperty("precision").GetString());Assert.Equal("Google Maps",item.GetProperty("attribution").GetString());Assert.True(item.GetProperty("expiresAt").GetDateTimeOffset()>DateTimeOffset.UtcNow.AddDays(29));await Expect(await Send(c,HttpMethod.Get,$"/crm/branches/{b.Branch}/navigation?provider=APPLE"),HttpStatusCode.Conflict);Assert.Equal(0L,await S("SELECT count(*)FROM crm.collaboration_changes WHERE company_id=@c AND snapshot?'latitude'",("c",db.Company)));}
 [Fact]public async Task Address_edit_during_provider_call_discards_stale_result()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));await Run(new(callback:async()=>{await S("UPDATE crm.customer_branches SET address_line1='20 Changed Street'WHERE company_id=@c AND id=@id",("c",db.Company),("id",b.Branch));}));Assert.Equal("STALE",(await Get(c,$"/crm/geocode-jobs/{id}")).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM crm.branch_geocodes WHERE company_id=@c",("c",db.Company)));await Expect(await Queue(c,b.Branch,version:1),HttpStatusCode.Conflict);await Expect(await Queue(c,b.Branch,version:2),HttpStatusCode.Accepted);}
 [Fact]public async Task Existing_coordinates_become_stale_when_branch_changes()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);await Expect(await Coordinates(c,b.Branch),HttpStatusCode.OK);await S("UPDATE crm.customer_branches SET address_line1='Changed'WHERE company_id=@c AND id=@id",("c",db.Company),("id",b.Branch));var map=(await Get(c,"/crm/map/branches?geocodeState=STALE")).GetProperty("items")[0];Assert.Equal(JsonValueKind.Null,map.GetProperty("latitude").ValueKind);Assert.False((await Get(c,$"/crm/branches/{b.Branch}/navigation")).GetProperty("usesCoordinates").GetBoolean());}
 [Fact]public async Task Manual_confirmation_wins_over_late_automatic_result()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted);await Run(new(callback:async()=>{await Expect(await Coordinates(c,b.Branch,-34,150),HttpStatusCode.OK);}));var row=(await Get(c,"/crm/map/branches")).GetProperty("items")[0];Assert.Equal("MANUAL",row.GetProperty("source").GetString());Assert.Equal(-34,D(row.GetProperty("latitude")));}
 [Theory][InlineData(false)][InlineData(true)]public async Task Revoked_map_permission_before_or_during_call_discards_result(bool during)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));async Task Revoke(){await S("DELETE FROM identity.role_permissions WHERE company_id=@c AND permission_code='crm.maps.manage'",("c",db.Company));}if(!during)await Revoke();var fake=new Geocoder(callback:during?Revoke:null);await Run(fake);Assert.Equal(during?1:0,fake.Calls);Assert.Equal("FAILED",await S("SELECT state FROM crm.geocode_jobs WHERE id=@id",("id",id)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.branch_geocodes WHERE company_id=@c",("c",db.Company)));}
 [Fact]public async Task Transient_errors_stop_at_five_and_manual_retry_can_recover()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));for(var n=0;n<5;n++){await S("UPDATE crm.geocode_jobs SET available_at=now()WHERE id=@id",("id",id));await Run(new("temporary"));}Assert.Equal("FAILED",(await Get(c,$"/crm/geocode-jobs/{id}")).GetProperty("state").GetString());await Expect(await Send(c,HttpMethod.Post,$"/crm/geocode-jobs/{id}/retry"),HttpStatusCode.OK);await Run(new());Assert.Equal("SUCCEEDED",(await Get(c,$"/crm/geocode-jobs/{id}")).GetProperty("state").GetString());}
 [Fact]public async Task Expired_cache_is_removed_and_same_address_can_be_queued_again()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));await Run(new());await S("UPDATE crm.branch_geocodes SET expires_at=now()-interval '1 second'WHERE company_id=@c",("c",db.Company));await using(var src=NpgsqlDataSource.Create(db.Worker))Assert.False(await new GeocodeWorker(src,new Geocoder()).ProcessOneAsync());Assert.Equal(0L,await S("SELECT count(*)FROM crm.branch_geocodes WHERE company_id=@c",("c",db.Company)));var queued=await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted);Assert.Equal(id,Id(queued));Assert.Equal("PENDING",queued.GetProperty("state").GetString());await Run(new());}
 [Theory][InlineData(false)][InlineData(true)]public async Task Late_audit_failure_rolls_back_coordinates_or_queue_and_original_key_retries(bool queue)
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var key=Code();Task<HttpResponseMessage> Action()=>queue?Queue(c,b.Branch,key):Coordinates(c,b.Branch,key:key);var name=queue?"geocode":"coordinates";await S($"CREATE FUNCTION crm.test_c05_mapfail()RETURNS trigger LANGUAGE plpgsql AS $$BEGIN IF NEW.company_id='{db.Company}'AND NEW.action='crm.collaboration_{name}'THEN RAISE EXCEPTION 'Injected' USING ERRCODE='HR422';END IF;RETURN NEW;END$$;CREATE TRIGGER test_c05_mapfail BEFORE INSERT ON platform.audit_events FOR EACH ROW EXECUTE FUNCTION crm.test_c05_mapfail()");try{await Expect(await Action(),HttpStatusCode.UnprocessableEntity);Assert.Equal(0L,await S("SELECT count(*)FROM crm.branch_geocodes WHERE company_id=@c",("c",db.Company)));Assert.Equal(0L,await S("SELECT count(*)FROM crm.geocode_jobs WHERE company_id=@c",("c",db.Company)));}finally{await S("DROP TRIGGER test_c05_mapfail ON platform.audit_events;DROP FUNCTION crm.test_c05_mapfail()");}await Expect(await Action(),queue?HttpStatusCode.Accepted:HttpStatusCode.OK);}
 private sealed class Handler(HttpStatusCode status,string body):HttpMessageHandler{public int Calls;protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage r,CancellationToken ct){Calls++;Assert.Equal("maps.googleapis.com",r.RequestUri!.Host);Assert.Contains("country%3AAU",r.RequestUri.OriginalString);return Task.FromResult(new HttpResponseMessage(status){Content=new StringContent(body)});}}
 private static string GoogleBody(string status="OK",bool partial=false,int count=1)=>JsonSerializer.Serialize(new{status,results=Enumerable.Range(0,count).Select(_=>new{partial_match=partial,address_components=new[]{new{short_name="AU",types=new[]{"country"}}},geometry=new{location=new{lat=-33.86,lng=151.21},location_type="ROOFTOP"},place_id="test-place"})});
 [Theory][InlineData(429,true)][InlineData(503,true)][InlineData(302,false)][InlineData(400,false)]public async Task Google_HTTP_failure_classification_avoids_provider_payload_leaks(int status,bool retry)
 {var h=new Handler((HttpStatusCode)status,"sensitive provider response");var g=new GoogleBranchGeocoder(new(){ApiKey="test-key"},new HttpClient(h));var error=await Assert.ThrowsAsync<DocumentWorkException>(()=>g.LocateAsync(JsonSerializer.SerializeToElement(new{address="10 Test Street",country="AU"}),default));Assert.Equal(retry?WorkFailure.Retry:WorkFailure.Permanent,error.Failure);Assert.DoesNotContain("sensitive",error.Code);Assert.Equal(1,h.Calls);}
 [Theory][InlineData("ZERO_RESULTS",false,1,"geocode_no_result")][InlineData("OVER_QUERY_LIMIT",false,1,"geocode_transient")][InlineData("OK",true,1,"geocode_partial_match")][InlineData("OK",false,2,"geocode_ambiguous")]
 public async Task Google_application_errors_and_ambiguous_matches_do_not_silently_choose_coordinates(string status,bool partial,int count,string error)
 {var h=new Handler(HttpStatusCode.OK,GoogleBody(status,partial,count));var g=new GoogleBranchGeocoder(new(){ApiKey="test-key"},new HttpClient(h));Assert.Equal(error,(await Assert.ThrowsAsync<DocumentWorkException>(()=>g.LocateAsync(JsonSerializer.SerializeToElement(new{address="10 Test Street",country="AU"}),default))).Code);}
 [Fact]public async Task Google_adapter_maps_valid_precision_and_unconfigured_adapter_never_calls_network()
 {var h=new Handler(HttpStatusCode.OK,GoogleBody());var address=JsonSerializer.SerializeToElement(new{address="10 Test Street",country="AU"});var g=new GoogleBranchGeocoder(new(){ApiKey="test-key"},new HttpClient(h));var result=await g.LocateAsync(address,default);Assert.Equal("ROOFTOP",result.GetProperty("precision").GetString());var empty=new GoogleBranchGeocoder(new(),new HttpClient(h));Assert.Equal("geocoder_unconfigured",(await Assert.ThrowsAsync<DocumentWorkException>(()=>empty.LocateAsync(address,default))).Code);Assert.Equal(1,h.Calls);}

 [Fact]public async Task Concurrent_geocode_claim_and_expired_lease_recovery_fence_stale_completion()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));await S("DELETE FROM crm.geocode_jobs WHERE company_id<>@c",("c",db.Company));async Task<Guid?> Claim(){await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var cmd=new NpgsqlCommand("SELECT lease FROM crm.claim_geocode()",con);var v=await cmd.ExecuteScalarAsync();return v is Guid g?g:null;}var both=await Task.WhenAll(Claim(),Claim());Assert.Single(both,x=>x is not null);var old=both.Single(x=>x is not null)!.Value;await S("UPDATE crm.geocode_jobs SET lease_until=now()-interval '1 second'WHERE id=@id",("id",id));var next=(await Claim())!.Value;Assert.NotEqual(old,next);await using var con=new NpgsqlConnection(db.Worker);await con.OpenAsync();await using var done=new NpgsqlCommand("SELECT crm.finish_geocode(@id,@lease,'FAILED','stale',NULL)",con);done.Parameters.AddWithValue("id",id);done.Parameters.AddWithValue("lease",old);Assert.Equal("HR409",(await Assert.ThrowsAsync<PostgresException>(()=>done.ExecuteNonQueryAsync())).SqlState);Assert.Equal("PROCESSING",await S("SELECT state FROM crm.geocode_jobs WHERE id=@id",("id",id)));}
 private sealed class InvalidGeocoder:IBranchGeocoder{public Task<JsonElement> LocateAsync(JsonElement address,CancellationToken ct)=>Task.FromResult(JsonSerializer.SerializeToElement(new{bad="output"}));}
 [Fact]public async Task Invalid_adapter_output_is_failed_without_coordinates_or_repeated_economic_facts()
 {await using var api=new TestApi(db);using var c=api.Authenticated();var b=await Branch(c);var id=Id(await Expect(await Queue(c,b.Branch),HttpStatusCode.Accepted));await S("DELETE FROM crm.geocode_jobs WHERE company_id<>@c",("c",db.Company));await using var source=NpgsqlDataSource.Create(db.Worker);await new GeocodeWorker(source,new InvalidGeocoder()).ProcessOneAsync();Assert.Equal("FAILED",(await Get(c,$"/crm/geocode-jobs/{id}")).GetProperty("state").GetString());Assert.Equal(0L,await S("SELECT count(*)FROM crm.branch_geocodes WHERE company_id=@c",("c",db.Company)));}
}
